import type { Spec } from './NativeBloomVideo';

declare const require: (id: string) => unknown;

let native: Spec | undefined;

/** The TurboModule, loaded on first use (a web bundle or a Node test never loads it). */
function module(): Spec {
  if (!native) {
    const found = (require('./NativeBloomVideo') as { default: Spec | null }).default;
    if (!found) throw new Error('Bloom: the native module BloomVideo is not in this build (bloom build android links it)');
    native = found;
  }
  return native;
}

/** The native module is linked (always true in a `bloom build`; false on the web and in tests). */
export function isAvailable(): boolean {
  if (native) return true;
  try {
    return module() !== undefined;
  } catch {
    return false;
  }
}

