type Host = ComponentType<Record<string, unknown>>;

/** A native view takes the space it is offered (a `.frame()` sizes it). */
const FILL = { flexGrow: 1, alignSelf: 'stretch' } as const;

/** The native component `name`, or `null` where the build does not link it (the web, tests). */
function hostOf(name: string, load: () => unknown): Host | null {
  try {
    const { UIManager } = require('react-native') as {
      UIManager?: { hasViewManagerConfig?: (name: string) => boolean };
    };
    if (UIManager?.hasViewManagerConfig?.(name) !== true) return null;
    return (load() as { default: Host }).default;
  } catch {
    return null;
  }
}

let BloomVideoViewHost: Host | null | undefined;

/** The native view `BloomVideoView` (a Fabric component). It draws nothing where the build does not link it. */
export function BloomVideoView(player: number, contentFit: 'contain' | 'cover' | 'fill', onFirstFrame: ((event: { readonly player: number }) => void) | undefined): Child {
  if (BloomVideoViewHost === undefined) BloomVideoViewHost = hostOf('BloomVideoView', () => require('./BloomVideoViewNativeComponent'));
  if (BloomVideoViewHost === null) return Embed(null);
  return Embed(
    createElement(BloomVideoViewHost, {
      style: FILL,
    player,
    contentFit,
    onFirstFrame: onFirstFrame === undefined ? undefined : (e: { nativeEvent: { player: number } }) => onFirstFrame(e.nativeEvent),
    }) as Parameters<typeof Embed>[0],
  );
}
